function bars(vals, color) {
  const max = Math.max(...vals); const w = 300, h = 70, bw = w / vals.length;
  return `<svg viewBox="0 0 ${w} ${h + 14}" width="100%" role="img" aria-label="일별 덤프 추이">` +
    vals.map((v, i) => { const bh = (v / max) * h; return `<rect x="${i * bw + 2}" y="${h - bh}" width="${bw - 4}" height="${bh}" rx="2" fill="${i >= vals.length - 7 ? color : '#c7cdd8'}"/>`; }).join('') +
    `<text x="0" y="${h + 12}" font-size="9" fill="#6b7280">지난주</text><text x="${w}" y="${h + 12}" font-size="9" fill="#6b7280" text-anchor="end">이번 주</text></svg>`;
}

