:root[data-theme="dark"]{--bg:#111317;--card:#171a1f;--ink:#e6e9ee;--sub:#a0a8b6;--line:#2a2f38;--soft:#1f2433}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:"Noto Sans KR",system-ui,sans-serif;line-height:1.6;word-break:keep-all}
.wrap{max-width:1120px;margin:0 auto;padding:0 16px}
.tag{display:inline-block;background:var(--soft);color:var(--brand);font-weight:700;font-size:13px;padding:4px 12px;border-radius:99px}
.hero{display:grid;grid-template-columns:1fr 1.15fr;gap:36px;align-items:center;padding:56px 0 24px}
h1{font-size:clamp(30px,4.6vw,48px);line-height:1.2;margin:14px 0 12px;font-weight:900;letter-spacing:-.02em}
h1 em{font-style:normal;color:var(--brand)}
.lead{font-size:18px;color:var(--sub);margin:0 0 18px}
.bl{background:var(--card);border:2px solid var(--brand);border-radius:14px;padding:16px 20px}
.bl b.k{color:var(--brand)}.bl ul{margin:6px 0 0;padding-left:20px}
h2{font-size:clamp(22px,3vw,30px);margin:64px 0 6px;font-weight:900;letter-spacing:-.01em}
.h2s{color:var(--sub);margin:0 0 22px;font-size:16px}
.map{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.map .col{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;border-top:5px solid var(--c)}
.map h4{margin:0 0 8px;font-size:15px}
.map a{display:block;color:var(--ink);text-decoration:none;font-size:14px;padding:5px 8px;border-radius:8px;margin:2px -8px}
.map a:hover{background:var(--soft)}
.grp{display:flex;align-items:center;gap:10px;margin:56px 0 16px}
.grp span{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;color:#fff;font-size:18px;background:var(--c)}
.grp h3{margin:0;font-size:22px}
.feat{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:24px;margin-bottom:18px;scroll-margin-top:16px}
.fh{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:baseline}
.fn{font-weight:800;font-size:14px;color:var(--c)}
.sk{font-family:Consolas,monospace;font-size:12.5px;background:var(--soft);padding:2px 8px;border-radius:6px;color:var(--sub)}
