const TERM_JS = `
(function(){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 const wait=ms=>new Promise(r=>setTimeout(r,ms));
 async function play(t){
  const lines=[...t.querySelectorAll('.ln')];
  const texts=lines.map(l=>l.textContent);
  for(;;){
   lines.forEach(l=>{l.style.display='none';});
   for(let i=0;i<lines.length;i++){
    const l=lines[i]; l.style.display='';
    if(l.classList.contains('u')){
     l.textContent='';const cur=document.createElement('span');cur.className='cur';l.appendChild(cur);
     for(const ch of texts[i]){cur.before(ch);await wait(45);}
     await wait(350);cur.remove();
    } else { await wait(l.classList.contains('c')?420:650); }
   }
   await wait(4200);
  }
 }
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!e.target.dataset.on){e.target.dataset.on=1;play(e.target);}}),{threshold:.35});
 document.querySelectorAll('.term').forEach(t=>io.observe(t));
})();`;

