${phone('모니터', `<p class="m-h">오늘 시스템 상태</p><div class="m-row" style="margin-bottom:8px"><div class="m-kpi"><small>덤프</small><b>12</b><small class="dn">▼ 4</small></div><div class="m-kpi"><small>잡 실패</small><b>1</b><small class="up">▲ 1</small></div></div><div class="m-row"><div class="m-kpi"><small>IDoc 오류</small><b>5</b></div><div class="m-kpi"><small>업데이트</small><b>0</b></div></div><div class="m-box b-bad" style="font-size:11px">야간 정산 잡 중단 · 02:14</div><div class="m-box b-ok" style="font-size:11px">이관 3건 · 오늘 밤 가도 됨</div>`)}
${phone('승인', `<div class="bubble b-me">출하 보류 해제해줘 (오더 10004512)</div><div class="bubble b-ai"><b>바꾸기 전에 확인해 주세요.</b><table class="m-t"><tr><th>항목</th><th>지금</th><th>변경</th></tr><tr><td>출하 보류</td><td>01</td><td><b>해제</b></td></tr></table><div style="margin-top:8px"><span class="btn-m bk">예</span><span class="btn-m bl">취소</span></div></div>`)}</div></section>`;

  for (const g of GROUPS) {
    h += `<div class="grp" style="--c:${g.color}"><span>${g.icon}</span><h3>${g.name}</h3></div>`;
    for (const f of FEATURES.filter((x) => x.g === g.id)) {
      const menu = WEBMENU[f.id];
      const u = f.term.find((t) => t[0] === 'u')[1];
      const chatLike = menu === '채팅';
      const body = chatLike && f.mock === 'symptom' ? `<div class="bubble b-me">${u}</div><div class="bubble b-ai" style="max-width:100%">${M.symptom()}</div>` : M[f.mock]();
      h += `<section class="feat" id="w-${f.id}" style="--c:${g.color}">${featHead(f).replace(`/sc4sap:${f.skill}`, `메뉴: ${menu}`)}
<div class="vis"><div><p class="cap">① 이렇게 요청해요</p>${appShot(chatLike ? 'chat' : 'skills/' + f.skill.split(' ')[0], menu, f.name, `<div class="bubble b-me" style="max-width:100%">${u}</div><div class="prog" style="margin-top:8px">${f.term.filter((t) => t[0] === 'c').map((t) => `<div class="ok">✓ ${t[1]}</div>`).join('')}<div class="run">● ${f.term[f.term.length - 1][1]}</div></div>`)}</div>
<div><p class="cap">② 웹 화면에 이렇게 나와요</p>${appShot(chatLike ? 'chat' : 'runs/' + f.id, menu, f.name, body)}</div></div></section>`;
    }
  }
  h += more.replace('이 밖에도 있어요', '이 밖에도 있어요 (스킬 메뉴)') + safety(true) + compare(true);
  h += `<h2>시작은 이렇게 해요</h2><p class="h2s">설치 파일이 없어요.</p><ol class="steps">
<li>Basis가 SAP 웹 포트와 접속 권한을 열어줘요.</li><li>sc4sap.dev에 가입해요.</li><li>우리 SAP 접속 정보를 등록해요.</li><li>채팅에 평소 말투로 물어보면 끝.</li></ol>
<footer>화면 예시는 모두 샘플 데이터예요. · sc4sap.dev (베타) · SAP ECC / S/4HANA 온프레미스</footer></div></body></html>`;
  return h;
}

writeFileSync(`${OUT}/sc4sap_플러그인_핵심기능.html`, plugin());
writeFileSync(`${OUT}/sc4sap_웹_핵심기능.html`, web());
console.log('written');

