import { writeFileSync } from 'node:fs';
import { MOCK_CSS, M, shot } from './mocks.mjs';
import { GROUPS, FEATURES, MORE } from './features.mjs';

const OUT = process.argv[2];
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const G = Object.fromEntries(GROUPS.map((g) => [g.id, g]));

const PAGE_CSS = (brand, soft) => `
:root{--bg:#f5f6f8;--card:#fff;--ink:#1c2029;--sub:#5b6474;--line:#e3e6ee;--brand:${brand};--soft:${soft}}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#111317;--card:#171a1f;--ink:#e6e9ee;--sub:#a0a8b6;--line:#2a2f38;--soft:#1f2433}}
:root[data-theme="dark"]{--bg:#111317;--card:#171a1f;--ink:#e6e9ee;--sub:#a0a8b6;--line:#2a2f38;--soft:#1f2433}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:"Noto Sans KR",system-ui,sans-serif;line-height:1.6;word-break:keep-all}
.wrap{max-width:1120px;margin:0 auto;padding:0 16px}
.tag{display:inline-block;background:var(--soft);color:var(--brand);font-weight:700;font-size:13px;padding:4px 12px;border-radius:99px}
.hero{display:grid;grid-template-columns:1fr 1.15fr;gap:36px;align-items:center;padding:56px 0 24px}
h1{font-size:clamp(30px,4.6vw,48px);line-height:1.2;margin:14px 0 12px;font-weight:900;letter-spacing:-.02em}
h1 em{font-style:normal;color:var(--brand)}
.lead{font-size:18px;color:var(--sub);margin:0 0 18px}
.bl{background:var(--card);border:2px solid var(--brand);border-radius:14px;padding:16px 20px}
.bl b.k{color:var(--brand)}.bl ul{margin:6px 0 0;padding-left:20px}
h2{font-size:clamp(22px,3vw,30px);margin:64px 0 6px;font-weight:900;letter-spacing:-.01em}
.h2s{color:var(--sub);margin:0 0 22px;font-size:16px}
.map{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.map .col{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;border-top:5px solid var(--c)}
.map h4{margin:0 0 8px;font-size:15px}
.map a{display:block;color:var(--ink);text-decoration:none;font-size:14px;padding:5px 8px;border-radius:8px;margin:2px -8px}
.map a:hover{background:var(--soft)}
.grp{display:flex;align-items:center;gap:10px;margin:56px 0 16px}
.grp span{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;color:#fff;font-size:18px;background:var(--c)}
.grp h3{margin:0;font-size:22px}
.feat{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:24px;margin-bottom:18px;scroll-margin-top:16px}
.fh{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:baseline}
.fn{font-weight:800;font-size:14px;color:var(--c)}
.sk{font-family:Consolas,monospace;font-size:12.5px;background:var(--soft);padding:2px 8px;border-radius:6px;color:var(--sub)}
.feat h3.t{font-size:clamp(19px,2.4vw,24px);margin:4px 0 6px;line-height:1.35}
.feat p.d{margin:0 0 12px;color:var(--sub)}
.ba{display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:14px;margin-bottom:16px}
.ba .b{background:#fdf2e3;color:#92400e;border-radius:8px;padding:3px 10px}
.ba .a{background:#e5f6ef;color:#0f6b4a;border-radius:8px;padding:3px 10px;font-weight:700}
.vis{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}
.cap{font-size:12.5px;color:var(--sub);margin:0 0 6px;font-weight:700}
.term{background:#15161e;color:#c9d1e0;border-radius:12px;font-family:Consolas,"D2Coding",monospace;font-size:12.5px;overflow:hidden;box-shadow:0 10px 30px rgba(0,0,0,.25);min-height:260px}
.term .tb{background:#22242f;padding:8px 12px;display:flex;gap:6px;align-items:center;color:#7f8799;font-size:11px}
.term .tb i{width:10px;height:10px;border-radius:50%;background:#ff5f57}.term .tb i:nth-child(2){background:#febc2e}.term .tb i:nth-child(3){background:#28c840}
.term .tb b{margin-left:8px;font-weight:400}
.term .bd{padding:12px 14px}
.term .ln{white-space:pre-wrap;margin:2px 0}
.ln.u{color:#fff;background:#2a2d3a;border-radius:6px;padding:4px 8px;margin:4px 0 8px}
.ln.u::before{content:"> ";color:#d97757}
.ln.s::before{content:"● ";color:#d97757}.ln.s{color:#e8b48f;font-weight:700}
.ln.c{color:#8b93a7;padding-left:14px}.ln.c::before{content:"⎿  ";color:#555b6b}
.ln.r{color:#e2e8f0;padding-left:0}.ln.r::before{content:"● ";color:#fff}
.ln.d{color:#4ade80}.ln.d::before{content:"✓ "}
.cur{display:inline-block;width:7px;height:14px;background:#d97757;vertical-align:-2px;animation:bk 1s steps(1) infinite}
@keyframes bk{50%{opacity:0}}
.more{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px}
.more div{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px;font-size:14px}
.more code{display:block;color:var(--brand);font-size:12.5px;margin-bottom:2px}
.safe{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}
.safe div{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px}
.safe b{display:block;margin-bottom:2px}
.cmp{width:100%;border-collapse:collapse;background:var(--card);border-radius:12px;overflow:hidden;font-size:15px}
.cmp th,.cmp td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
.cmp th{background:var(--soft)}
.steps{counter-reset:s;list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.steps li{counter-increment:s;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:44px 14px 14px;position:relative;font-size:14.5px}
.steps li::before{content:counter(s);position:absolute;left:14px;top:12px;width:26px;height:26px;border-radius:50%;background:var(--brand);color:#fff;font-weight:700;display:grid;place-items:center;font-size:13px}
footer{color:var(--sub);font-size:13.5px;padding:48px 0 60px}
/* web app shell */
.app{display:grid;grid-template-columns:118px 1fr;min-height:300px;background:#f5f6f8}
.rail{background:#eceef2;padding:10px 6px;font-size:11px;color:#4b5563;border-right:1px solid #dde1e7}
.rail .lg{font-weight:900;color:#2f3540;font-size:13px;padding:2px 6px 10px}
.rail div.it{padding:4px 7px;border-radius:6px;margin:1px 0;white-space:nowrap}
.rail div.on{background:#2f3540;color:#fff;font-weight:700}
.main{padding:12px;min-width:0}
.topb{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;font-size:11px;color:#6b7280}
.topb b{color:#1f2430;font-size:13px}
.sys{background:#dcfce7;color:#15803d;border-radius:99px;padding:1px 8px;font-weight:700}
.shot .main .shot-in{background:#fff;border:1px solid #e3e6ee;border-radius:8px;padding:12px}
.phones{display:flex;gap:28px;justify-content:center;flex-wrap:wrap}
.phone{width:250px;background:#111;border-radius:34px;padding:10px;box-shadow:0 18px 40px rgba(0,0,0,.25)}
.phone .scr{background:#fff;border-radius:26px;overflow:hidden;min-height:470px;font-size:12px;color:#1f2430}
.phone .nt{height:22px;display:flex;justify-content:center;align-items:center}.phone .nt i{width:70px;height:6px;background:#111;border-radius:6px}
.phone .ph{display:flex;justify-content:space-between;padding:6px 14px;border-bottom:1px solid #eceef2;font-weight:800}
.phone .pb{padding:10px}
.inp{display:flex;gap:6px;margin-top:10px}.inp span{flex:1;background:#f0f2f5;border-radius:99px;padding:6px 12px;color:#9ca3af;font-size:11px}
.inp b{background:#2f3540;color:#fff;border-radius:99px;padding:6px 12px;font-size:11px}
.cost{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:10px 0}
.cost div{border:1.5px solid #dde1e7;border-radius:8px;padding:8px}.cost div.on{border-color:#2f3540;background:#f8f9fb}
.cost b{display:block;font-size:13px}
.fld{margin:6px 0}.fld small{display:block;color:#6b7280}.fld span{display:block;border:1px solid #d6dbe2;border-radius:6px;padding:4px 8px;background:#fff}
.prog div{display:flex;gap:6px;align-items:center;padding:3px 0;font-size:11px}.prog .ok{color:#15803d}.prog .run{color:#2563eb;font-weight:700}
@media (max-width:900px){.hero,.vis{grid-template-columns:1fr}.map{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:1fr 1fr}}
@media (max-width:560px){.map,.steps{grid-template-columns:1fr}.feat{padding:16px}.app{grid-template-columns:76px 1fr}.rail{font-size:10px}.hero{padding-top:32px}}
@media (prefers-reduced-motion:reduce){.cur{animation:none}}
@media print{.feat{break-inside:avoid}}
`;

const TERM_JS = `
(function(){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 const wait=ms=>new Promise(r=>setTimeout(r,ms));
 async function play(t){
  const lines=[...t.querySelectorAll('.ln')];
  const texts=lines.map(l=>l.textContent);
  for(;;){
   lines.forEach(l=>{l.style.display='none';});
   for(let i=0;i<lines.length;i++){
    const l=lines[i]; l.style.display='';
    if(l.classList.contains('u')){
     l.textContent='';const cur=document.createElement('span');cur.className='cur';l.appendChild(cur);
     for(const ch of texts[i]){cur.before(ch);await wait(45);}
     await wait(350);cur.remove();
    } else { await wait(l.classList.contains('c')?420:650); }
   }
   await wait(4200);
  }
 }
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!e.target.dataset.on){e.target.dataset.on=1;play(e.target);}}),{threshold:.35});
 document.querySelectorAll('.term').forEach(t=>io.observe(t));
})();`;

const term = (f, title = 'Claude Code · sc4sap') => `<div class="term" aria-label="터미널 사용 예시"><div class="tb"><i></i><i></i><i></i><b>${title}</b></div><div class="bd">${f.term.map(([t, s]) => `<div class="ln ${t}">${esc(s)}</div>`).join('')}</div></div>`;

const head = (title, brand, soft) => `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title}</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>${PAGE_CSS(brand, soft)}${MOCK_CSS}</style></head><body><div class="wrap">`;

const mapBlock = (link) => `<div class="map">${GROUPS.map((g) => `<div class="col" style="--c:${g.color}"><h4>${g.icon} ${g.name}</h4>${FEATURES.filter((f) => f.g === g.id).map((f) => `<a href="#${link}${f.id}">${f.name}</a>`).join('')}</div>`).join('')}</div>`;

const featHead = (f) => `<div class="fh"><span class="fn">${f.name}</span><span class="sk">/sc4sap:${f.skill}</span></div>
<h3 class="t">${f.title}</h3><p class="d">${f.desc}</p>
<div class="ba"><span class="b">지금: ${f.before}</span>→<span class="a">sc4sap: ${f.after}</span></div>`;

const safety = (web) => `<h2>걱정하실 부분, 먼저 막아뒀어요</h2><p class="h2s">AI가 운영 시스템을 망칠 수 없게 설계했어요.</p>
<div class="safe">
<div><b>🔒 QA·PRD는 읽기 전용</b>${web ? '운영 시스템에는 변경 요청이 나가지 않아요.' : '훅과 MCP 서버, 두 겹으로 변경을 막아요.'}</div>
<div><b>✋ 바꾸기 전엔 항상 승인</b>업무 문서는 미리보기를 보고 "예"를 해야 바뀌어요.</div>
<div><b>🧱 SAP 표준은 안 건드려요</b>고객 객체(Z·Y)만 바꿔요. 모든 변경은 이관 요청에 담겨요.</div>
<div><b>🙈 민감 데이터 보호</b>차단 목록으로 먼저 걸러요. 테스트 데이터는 마스킹해요.</div>
${web ? '<div><b>💰 실행 전 비용 미리보기</b>무거운 작업은 예상 비용을 보고 시작해요.</div>' : '<div><b>🔑 비밀번호는 OS 보관함에</b>프로젝트 파일에 남기지 않아요.</div>'}
</div>`;

const compare = (web) => `<h2>${web ? '웹과 플러그인' : '플러그인과 웹'}, 무엇을 쓸까요?</h2><p class="h2s">한 줄 요약: 개발까지 직접 하면 플러그인, 어디서든 보고·조회하면 웹이에요. 결과물은 같아요.</p>
<table class="cmp"><tr><th></th><th>플러그인${web ? '' : ' (이 문서)'}</th><th>웹 · sc4sap.dev${web ? ' (이 문서)' : ''}</th></tr>
<tr><td><b>설치</b></td><td>PC에 Claude Code + 플러그인</td><td>없음 · 브라우저와 휴대폰</td></tr>
<tr><td><b>잘 맞는 사람</b></td><td>개발자, 모듈 컨설턴트, 운영 담당</td><td>운영팀장, PM·PMO, 현업 리더</td></tr>
<tr><td><b>쓰는 방식</b></td><td>터미널에서 말로 요청</td><td>채팅 + 메뉴 화면</td></tr>
<tr><td><b>강점</b></td><td>개발 · 테스트 · 이관을 한 흐름으로</td><td>외근·야간에도 장애와 보고서 확인</td></tr></table>`;

const more = `<h2>이 밖에도 있어요</h2><p class="h2s">필요할 때 꺼내 쓰는 도구들이에요.</p><div class="more">${MORE.map(([k, v]) => `<div><code>/sc4sap:${k}</code>${v}</div>`).join('')}</div>`;

// ---------- PLUGIN ----------
function plugin() {
  const hero = FEATURES[0];
  let h = head('sc4sap 플러그인 핵심기능', '#5b3fd6', '#efebff');
  h += `<section class="hero"><div><span class="tag">sc4sap 플러그인 · Claude Code</span>
<h1>SAP 일을<br><em>말 한마디로</em> 끝내요.</h1>
<p class="lead">sc4sap은 AI(Claude)를 우리 SAP에 직접 연결해요. AI가 시스템을 읽고, 원인을 찾고, 프로그램과 문서를 만들어요.</p>
<div class="bl"><b class="k">결론부터</b><ul><li>장애 분석 · 개발 · 문서 · 테스트 · 프로젝트 관리를 <b>AI 팀이</b> 해요.</li><li>결과는 <b>바로 쓰는 HTML 문서</b>로 나와요.</li><li>운영(PRD)은 읽기만, 변경은 <b>승인 후에만</b>. ECC · S/4HANA 모두 지원.</li></ul></div></div>
<div>${term(hero)}</div></section>`;
  h += `<h2>한눈에 보기</h2><p class="h2s">역할별 핵심 기능 ${FEATURES.length}가지예요. 누르면 해당 설명으로 가요.</p>${mapBlock('f-')}`;
  for (const g of GROUPS) {
    h += `<div class="grp" style="--c:${g.color}"><span>${g.icon}</span><h3>${g.name}</h3></div>`;
    for (const f of FEATURES.filter((x) => x.g === g.id)) {
      const out = f.file ? shot(f.file.includes('·') ? f.file : `.sc4sap/output/${f.file}`, M[f.mock]()) : shot('Claude Code 대화 화면', M[f.mock]());
      h += `<section class="feat" id="f-${f.id}" style="--c:${g.color}">${featHead(f)}
<div class="vis"><div><p class="cap">① 이렇게 말해요</p>${term(f)}</div><div><p class="cap">② 이런 결과가 나와요</p>${out}</div></div></section>`;
    }
  }
  h += more + safety(false) + compare(false);
  h += `<h2>시작은 이렇게 해요</h2><p class="h2s">처음 한 번, 30~40분이면 돼요.</p><ol class="steps">
