@media (prefers-reduced-motion:reduce){.cur{animation:none}}
@media print{.feat{break-inside:avoid}}
`;

const TERM_JS = `
(function(){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 const wait=ms=>new Promise(r=>setTimeout(r,ms));
 async function play(t){
  const lines=[...t.querySelectorAll('.ln')];
  const texts=lines.map(l=>l.textContent);
  for(;;){
   lines.forEach(l=>{l.style.display='none';});
   for(let i=0;i<lines.length;i++){
    const l=lines[i]; l.style.display='';
    if(l.classList.contains('u')){
     l.textContent='';const cur=document.createElement('span');cur.className='cur';l.appendChild(cur);
     for(const ch of texts[i]){cur.before(ch);await wait(45);}
     await wait(350);cur.remove();
    } else { await wait(l.classList.contains('c')?420:650); }
   }
   await wait(4200);
  }
 }
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting&&!e.target.dataset.on){e.target.dataset.on=1;play(e.target);}}),{threshold:.35});
 document.querySelectorAll('.term').forEach(t=>io.observe(t));
})();`;

const term = (f, title = 'Claude Code · sc4sap') => `<div class="term" aria-label="터미널 사용 예시"><div class="tb"><i></i><i></i><i></i><b>${title}</b></div><div class="bd">${f.term.map(([t, s]) => `<div class="ln ${t}">${esc(s)}</div>`).join('')}</div></div>`;

const head = (title, brand, soft) => `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title}</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>${PAGE_CSS(brand, soft)}${MOCK_CSS}</style></head><body><div class="wrap">`;

const mapBlock = (link) => `<div class="map">${GROUPS.map((g) => `<div class="col" style="--c:${g.color}"><h4>${g.icon} ${g.name}</h4>${FEATURES.filter((f) => f.g === g.id).map((f) => `<a href="#${link}${f.id}">${f.name}</a>`).join('')}</div>`).join('')}</div>`;

const featHead = (f) => `<div class="fh"><span class="fn">${f.name}</span><span class="sk">/sc4sap:${f.skill}</span></div>
<h3 class="t">${f.title}</h3><p class="d">${f.desc}</p>
<div class="ba"><span class="b">지금: ${f.before}</span>→<span class="a">sc4sap: ${f.after}</span></div>`;

const safety = (web) => `<h2>걱정하실 부분, 먼저 막아뒀어요</h2><p class="h2s">AI가 운영 시스템을 망칠 수 없게 설계했어요.</p>
<div class="safe">
<div><b>🔒 QA·PRD는 읽기 전용</b>${web ? '운영 시스템에는 변경 요청이 나가지 않아요.' : '훅과 MCP 서버, 두 겹으로 변경을 막아요.'}</div>
<div><b>✋ 바꾸기 전엔 항상 승인</b>업무 문서는 미리보기를 보고 "예"를 해야 바뀌어요.</div>
<div><b>🧱 SAP 표준은 안 건드려요</b>고객 객체(Z·Y)만 바꿔요. 모든 변경은 이관 요청에 담겨요.</div>
<div><b>🙈 민감 데이터 보호</b>차단 목록으로 먼저 걸러요. 테스트 데이터는 마스킹해요.</div>
${web ? '<div><b>💰 실행 전 비용 미리보기</b>무거운 작업은 예상 비용을 보고 시작해요.</div>' : '<div><b>🔑 비밀번호는 OS 보관함에</b>프로젝트 파일에 남기지 않아요.</div>'}
</div>`;

const compare = (web) => `<h2>${web ? '웹과 플러그인' : '플러그인과 웹'}, 무엇을 쓸까요?</h2><p class="h2s">한 줄 요약: 개발까지 직접 하면 플러그인, 어디서든 보고·조회하면 웹이에요. 결과물은 같아요.</p>
<table class="cmp"><tr><th></th><th>플러그인${web ? '' : ' (이 문서)'}</th><th>웹 · sc4sap.dev${web ? ' (이 문서)' : ''}</th></tr>
<tr><td><b>설치</b></td><td>PC에 Claude Code + 플러그인</td><td>없음 · 브라우저와 휴대폰</td></tr>
<tr><td><b>잘 맞는 사람</b></td><td>개발자, 모듈 컨설턴트, 운영 담당</td><td>운영팀장, PM·PMO, 현업 리더</td></tr>
<tr><td><b>쓰는 방식</b></td><td>터미널에서 말로 요청</td><td>채팅 + 메뉴 화면</td></tr>
<tr><td><b>강점</b></td><td>개발 · 테스트 · 이관을 한 흐름으로</td><td>외근·야간에도 장애와 보고서 확인</td></tr></table>`;

const more = `<h2>이 밖에도 있어요</h2><p class="h2s">필요할 때 꺼내 쓰는 도구들이에요.</p><div class="more">${MORE.map(([k, v]) => `<div><code>/sc4sap:${k}</code>${v}</div>`).join('')}</div>`;

// ---------- PLUGIN ----------
function plugin() {
  const hero = FEATURES[0];
  let h = head('sc4sap 플러그인 핵심기능', '#5b3fd6', '#efebff');
  h += `<section class="hero"><div><span class="tag">sc4sap 플러그인 · Claude Code</span>
<h1>SAP 일을<br><em>말 한마디로</em> 끝내요.</h1>
<p class="lead">sc4sap은 AI(Claude)를 우리 SAP에 직접 연결해요. AI가 시스템을 읽고, 원인을 찾고, 프로그램과 문서를 만들어요.</p>
<div class="bl"><b class="k">결론부터</b><ul><li>장애 분석 · 개발 · 문서 · 테스트 · 프로젝트 관리를 <b>AI 팀이</b> 해요.</li><li>결과는 <b>바로 쓰는 HTML 문서</b>로 나와요.</li><li>운영(PRD)은 읽기만, 변경은 <b>승인 후에만</b>. ECC · S/4HANA 모두 지원.</li></ul></div></div>
<div>${term(hero)}</div></section>`;
  h += `<h2>한눈에 보기</h2><p class="h2s">역할별 핵심 기능 ${FEATURES.length}가지예요. 누르면 해당 설명으로 가요.</p>${mapBlock('f-')}`;
  for (const g of GROUPS) {
    h += `<div class="grp" style="--c:${g.color}"><span>${g.icon}</span><h3>${g.name}</h3></div>`;
    for (const f of FEATURES.filter((x) => x.g === g.id)) {
      const out = f.file ? shot(f.file.includes('·') ? f.file : `.sc4sap/output/${f.file}`, M[f.mock]()) : shot('Claude Code 대화 화면', M[f.mock]());
      h += `<section class="feat" id="f-${f.id}" style="--c:${g.color}">${featHead(f)}
<div class="vis"><div><p class="cap">① 이렇게 말해요</p>${term(f)}</div><div><p class="cap">② 이런 결과가 나와요</p>${out}</div></div></section>`;
    }
  }
  h += more + safety(false) + compare(false);
  h += `<h2>시작은 이렇게 해요</h2><p class="h2s">처음 한 번, 30~40분이면 돼요.</p><ol class="steps">
<li>Basis가 SAP 웹 포트와 ADT 권한을 열어줘요.</li><li>PC에 Claude Code를 설치해요.</li><li>sc4sap 플러그인을 추가하고 <b>/sc4sap:setup</b> 실행.</li><li>평소 말투로 물어보면 끝. 명령어를 외울 필요 없어요.</li></ol>
<footer>화면 예시는 모두 샘플 데이터예요. · 설치 안내: sc4sap.dev/install-guide.html · SAP ECC / S/4HANA 온프레미스</footer></div><script>${TERM_JS}</script></body></html>`;
  return h;
}

// ---------- WEB ----------
const RAIL = ['홈', '채팅', '모니터', '스킬', 'WBS', '주간 보고', 'UAT', '권한', '관계 그래프', '설정 문서', '스마트폼', '매뉴얼', '회의록'];
const WEBMENU = { symptom: '채팅', ops: '모니터', transport: '스킬', assist: '채팅', consultant: '채팅', create: '스킬', test: '스킬', review: '스킬', spec: '매뉴얼', config: '설정 문서', relmap: '관계 그래프', process: '스킬', dashboard: 'WBS', roles: '권한', uat: 'UAT', form: '스마트폼' };
const appShot = (path, active, title, body) => shot(`sc4sap.dev/${path}`, `<div class="app" style="margin:-14px"><div class="rail"><div class="lg">sc4sap</div>${RAIL.map((r) => `<div class="it${r === active ? ' on' : ''}">${r}</div>`).join('')}</div><div class="main"><div class="topb"><b>${title}</b><span class="sys">DEV 연결됨</span></div><div class="shot-in">${body}</div></div></div>`);

function web() {
  let h = head('sc4sap 웹 핵심기능', '#0a66c2', '#e6f0fb');
  const heroBody = `<div class="bubble b-me">어젯밤 청구 배치가 왜 덤프 났어?</div><div class="bubble b-ai" style="max-width:100%">${M.symptom()}</div>`;
  h += `<section class="hero"><div><span class="tag">sc4sap 웹 · sc4sap.dev (베타)</span>
<h1>설치 없이,<br><em>브라우저와 휴대폰</em>에서<br>SAP를 다뤄요.</h1>
<p class="lead">로그인하고 우리 SAP만 연결하면 돼요. 채팅으로 묻고, 메뉴에서 보고서와 문서를 받아요.</p>
<div class="bl"><b class="k">결론부터</b><ul><li>PC 설치가 <b>필요 없어요.</b> 외근·야간에도 휴대폰으로 확인해요.</li><li>플러그인과 <b>같은 결과물</b>을 웹 화면에서 받아요.</li><li>실행 전 <b>예상 비용</b>을 먼저 보여줘요. 운영(PRD)은 읽기만 해요.</li></ul></div></div>
<div>${appShot('chat', '채팅', '채팅', heroBody)}</div></section>`;
  h += `<h2>한눈에 보기</h2><p class="h2s">역할별 핵심 기능 ${FEATURES.length}가지예요. 누르면 해당 화면으로 가요.</p>${mapBlock('w-')}`;

  // signature screens
  h += `<h2>웹에서만 이런 게 편해요</h2><p class="h2s">세 화면이면 사용법이 끝나요.</p>`;
  h += `<section class="feat" style="--c:#0a66c2"><div class="fh"><span class="fn">스킬 실행</span><span class="sk">sc4sap.dev/skills</span></div>
<h3 class="t">버튼으로 고르고, 비용을 보고, 실행해요.</h3><p class="d">입력값을 채우고 Economy와 Standard 중 고르면 예상 비용이 먼저 나와요. 진행 상황은 실시간으로 보여요.</p>
<div class="vis"><div>${appShot('skills/ops-health-check', '스킬', '운영 보고서 만들기', `<div class="fld"><small>기간</small><span>2026-11-13 ~ 2026-11-19</span></div><div class="fld"><small>대상 시스템</small><span>PRD (읽기 전용)</span></div>
<div class="cost"><div><b>Economy</b>예상 ₩500 내외</div><div class="on"><b>Standard ✓</b>예상 ₩1,200 내외</div></div><span class="btn-m bk">실행</span>`)}</div>
<div>${appShot('skills/ops-health-check/run', '스킬', '실행 중 · 운영 보고서', `<div class="prog"><div class="ok">✓ 덤프 읽기 · 128건</div><div class="ok">✓ 배치 잡 · 중단 7건</div><div class="ok">✓ 업데이트 오류 · 3건</div><div class="run">⟳ IDoc 오류 집계 중…</div><div style="color:#9ca3af">○ 보고서 작성</div></div>
<div style="margin-top:10px;background:#f0f2f5;border-radius:99px;height:8px"><div style="width:72%;height:8px;border-radius:99px;background:#2563eb"></div></div>`)}</div></div></section>`;

  const phone = (title, body) => `<div class="phone"><div class="scr"><div class="nt"><i></i></div><div class="ph"><span>sc4sap</span><span style="font-weight:400;color:#6b7280">${title}</span></div><div class="pb">${body}</div></div></div>`;
  h += `<section class="feat" style="--c:#0a66c2"><div class="fh"><span class="fn">모바일</span><span class="sk">iPhone · Galaxy</span></div>
<h3 class="t">장애 전화가 오면, 노트북보다 휴대폰이 먼저예요.</h3><p class="d">VPN과 SAP GUI 없이 원인과 운영 지표를 바로 봐요.</p>
<div class="phones">${phone('채팅', `<div class="bubble b-me">오늘 아침 덤프 원인 알려줘</div><div class="bubble b-ai"><b>청구 배치 1건이 원인이에요.</b><div class="m-box b-bad" style="font-size:11px">결제조건 빈 값 → CONVT_NO_NUMBER</div><div class="m-box b-ok" style="font-size:11px">조치: 고객 3건 결제조건 보완</div></div><div class="inp"><span>무엇이든 물어보세요</span><b>↑</b></div>`)}
${phone('모니터', `<p class="m-h">오늘 시스템 상태</p><div class="m-row" style="margin-bottom:8px"><div class="m-kpi"><small>덤프</small><b>12</b><small class="dn">▼ 4</small></div><div class="m-kpi"><small>잡 실패</small><b>1</b><small class="up">▲ 1</small></div></div><div class="m-row"><div class="m-kpi"><small>IDoc 오류</small><b>5</b></div><div class="m-kpi"><small>업데이트</small><b>0</b></div></div><div class="m-box b-bad" style="font-size:11px">야간 정산 잡 중단 · 02:14</div><div class="m-box b-ok" style="font-size:11px">이관 3건 · 오늘 밤 가도 됨</div>`)}
