  for (const [name, tag] of [['sc4sap_플러그인_핵심기능.html', 'plugin'], ['sc4sap_웹_핵심기능.html', 'web']]) {
    for (const [w, h, sfx] of [[1280, 900, 'pc'], [390, 844, 'mo']]) {
