// Opens a visible browser on the local web app's sign-in page. The PERSON signs
// in by hand; when the app shows the home screen the session is saved to
// storage-state.json for the mobile checks (local file, git-ignored by the
// workspace, delete it to sign out: `node login.mjs --forget`).
//   node login.mjs [http://localhost:3000]
//   node login.mjs --auto   (test account from make-test-account.mjs, no window)
import { existsSync, readFileSync, unlinkSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";

const state = new URL("./storage-state.json", import.meta.url);
if (process.argv[2] === "--forget") {
  if (existsSync(state)) unlinkSync(state);
  console.log("forgotten");
  process.exit(0);
}
// --auto: no window — signs in with .test-account.json (make-test-account.mjs)
// and saves the session; the password is never printed.
if (process.argv[2] === "--auto") {
  const account = JSON.parse(readFileSync(new URL("./.test-account.json", import.meta.url), "utf8"));
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const res = await context.request.post(`${account.base}/api/auth/signin`, {
    headers: { origin: account.base },
    data: { email: account.email, password: account.password },
  });
  if (!res.ok()) {
    console.error(`Sign-in failed: ${res.status()}`);
    process.exit(1);
  }
