// Promo screenshots of the LOCAL web app (dev DB) with the QA test account.
//   node promoshots.mjs <outdir> <base> <w>x<h> <route> [<route> ...]
// Signs in with .test-account.json (password never printed), then shoots each route (viewport only).
import { readFileSync, mkdirSync } from "node:fs";
import { chromium } from "playwright";

const [out, base, size, ...routes] = process.argv.slice(2);
const host = new URL(base).hostname;
if (!["localhost", "127.0.0.1"].includes(host)) { console.error("Local dev host only."); process.exit(2); }
const [w, h] = size.split("x").map(Number);
mkdirSync(out, { recursive: true });
const account = JSON.parse(readFileSync(new URL("./.test-account.json", import.meta.url), "utf8"));
const browser = await chromium.launch();
const mobile = w < 600;
const context = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 2, isMobile: mobile, hasTouch: mobile, locale: "ko-KR" });
const res = await context.request.post(`${base}/api/auth/signin`, { headers: { origin: base }, data: { email: account.email, password: account.password } });
console.log("signin", res.status());
const page = await context.newPage();
for (const r of routes) {
  await page.goto(base + r, { waitUntil: "networkidle" }).catch(() => {});
  await page.waitForTimeout(1500);
  const name = (r.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "home") + (mobile ? "-mo" : "");
  await page.screenshot({ path: `${out}/${name}.png` });
  console.log(r, "->", page.url().replace(base, ""), name);
}
await browser.close();

