(() => {
  const zmap = new Map();
  const zname = (m) => { if (!zmap.has(m)) zmap.set(m, 'ZDEMO_' + String(zmap.size + 1).padStart(3, '0')); return zmap.get(m); };
  const rules = [
    [/[\w.+-]+@[\w-]+\.[\w.]+/g, 'demo@company.com'],
    [/Kim Sihun/g, 'Demo User'], [/Sihun/g, '데모'], [/김시훈|시훈/g, '데모'],
    [/\bCROWN\b/gi, 'DEMO'], [/\bSV\d_\d+\b/g, 'ORG_0001'],
    [/\b[A-Z0-9]{2,4}-(?:DEV|QAS|PRD|QA|PRO)\d*(?:-\d{3})?\b/g, 'DEV-100'],
    [/\b(?:ECP|ECD|ECQ|BXD|HKD|HKP|S4D|S4P)-?\d{0,3}\b/g, 'DEV-100'],
    [/\b[A-Z]{3}K9[0-9A-Z]{5}\b/g, 'DEVK900812'],
    [/\b[ZY](?=[A-Z0-9_]*[A-Z])[A-Z0-9_/]{3,}\b/g, (m) => (m.startsWith('ZDEMO') ? m : zname(m))],
  ];
  const fix = (s) => rules.reduce((t, [re, to]) => t.replace(re, to), s);
  const walk = (root) => {
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    for (let n = w.nextNode(); n; n = w.nextNode()) { const v = fix(n.nodeValue); if (v !== n.nodeValue) n.nodeValue = v; }
    root.querySelectorAll && root.querySelectorAll('input,textarea').forEach((e) => { if (e.value) e.value = fix(e.value); if (e.placeholder) e.placeholder = fix(e.placeholder); });
    root.querySelectorAll && root.querySelectorAll('[title]').forEach((e) => (e.title = fix(e.title)));
    document.querySelectorAll('iframe').forEach((f) => { try { f.contentDocument && walk(f.contentDocument.body); } catch (e) {} });
  };
  walk(document.body);
  if (!window.__mask) { window.__mask = new MutationObserver(() => walk(document.body)); window.__mask.observe(document.body, { childList: true, subtree: true, characterData: true }); }
  return 'masked ' + zmap.size;
})()

