window.__maskHtml = (s) => { const zmap = new Map(); const zname = (m) => { if (!zmap.has(m)) zmap.set(m, 'ZDEMO_' + String(zmap.size + 1).padStart(3, '0')); return zmap.get(m); }; const rules = [ [/[\w.+-]+@[\w-]+\.[a-z]{2,}(?:\.[a-z]{2,})?/g, 'demo@company.com'], [/Kim Sihun/g, 'Demo User'], [/\bCROWN\b/gi, 'DEMO'], [/\b[A-Z0-9]{2,4}-(?:DEV|QAS|PRD|QA|PRO)\d*(?:-\d{3})?\b/g, 'DEV-100'], [/\b(?:ECP|ECD|ECQ|BXD|HKD|HKP|S4D|S4P)-?\d{0,3}\b/g, 'DEV-100'], [/\b(?:ECD|ECP|BXD|HKD|S4D)K9\d{5}\b/g, (m)=>'DEVK9' + m.slice(-5)], [/\b[ZY](?=[A-Z0-9_]*[A-Z])[A-Z0-9_]{3,}\b/g, (m) => (m.startsWith('ZDEMO') ? m : zname(m))] ]; return s.split(/(<[^>]*>)/).map(p => p.startsWith('<') ? p : rules.reduce((t, [re, to]) => t.replace(re, to), p)).join(''); };
window.__maskFrames = async () => { const out = []; for (const f of document.querySelectorAll('iframe')) { const src = f.getAttribute('src'); if (!src || !src.includes('/api/')) continue; const html = await (await fetch(src, {credentials:'include'})).text(); f.removeAttribute('src'); f.srcdoc = window.__maskHtml(html); out.push(html.length); } return out; };
