// Web promo page from REAL workspace screenshots (masked before capture).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const OUT = process.argv[2];
const img = (n) => 'data:image/jpeg;base64,' + readFileSync(join(here, 'shots', n + '.jpg')).toString('base64');

const GROUPS = [
  { id: 'all', name: '공통', color: '#0a66c2', icon: '💬', menu: ['홈', '채팅'] },
  { id: 'ops', name: 'SM 운영', color: '#dc2626', icon: '🛠', menu: ['증상 분석', '권한 오류 분석', 'SAP 진단', '운영 보고서 작성', '비용', 'MCP 모니터'] },
  { id: 'pmo', name: 'PMO', color: '#d97706', icon: '📊', menu: ['프로젝트 대시보드', '데이터 이관', '회의록·할 일', '주간 현황', '컷오버 준비', 'CTS 점검', '권한 매트릭스'] },
  { id: 'con', name: '컨설턴트', color: '#0f8a5f', icon: '🧭', menu: ['도와줘! 컨설턴트!', '프로그램 비교', '프로그램 Spec 만들기', '프로그램 매뉴얼 만들기', '모듈 프로세스 BPH', 'Gap 분석', '컨피그 문서 만들기', '테스트 시나리오 만들기', '인터페이스 매핑 정의서', 'IMG 조회'] },
  { id: 'dev', name: '개발자', color: '#7c3aed', icon: '⌨', menu: ['코드 분석', 'CBO 오브젝트 수집', 'CBO 관계도', '프로그램 생성', '프로그램 테스트', 'DDIC 생성', 'Form 미리보기', 'PDF로 Form 만들기', '그래프'] },
];

// shots: [file, url path, caption]
const F = [
  { g: 'all', id: 'chat', menu: '채팅', title: '궁금한 건 채팅으로 물어요. AI가 우리 SAP를 직접 보고 답해요.',
    desc: 'T-code, 프로그램, 설정을 물으면 연결된 SAP에서 직접 찾아 답해요. 대화는 저장돼서 언제든 이어서 볼 수 있어요.',
    ba: ['컨설턴트·개발자에게 물어보고 기다리기', '바로 묻고 바로 답 받기'],
    shots: [['chat', 'chat', '채팅 — CS03이 뭐하는 트랜잭션인지 물어본 화면']] },

  { g: 'ops', id: 'cts', menu: 'CTS 점검', title: '이관 요청마다 "가도 됨 · 확인 · 불가"를 판정해요.',
    desc: '열린 작업, 비활성 객체, 다른 요청과 겹치는 객체, 순서 문제를 찾아요. 이관 전에 사유와 함께 한 장으로 받아요.',
    ba: ['운영에서 터지고 나서 발견', '이관 전에 판정표로 확인'],
    shots: [['cts-report', 'skills/transport-readiness', 'CTS 점검 결과 — 요청별 판정과 사유'], ['cts-page', 'skills/transport-readiness', '저장된 점검 문서와 입력 화면']] },
  { g: 'ops', id: 'auth', menu: '권한 오류 분석', title: '"권한이 없대요" — 사용자와 T-code만 넣으면 원인을 찾아요.',
    desc: '빠진 권한 객체와 값, 그 권한을 주는 후보 역할, 역할을 더하면 생기는 SoD 충돌까지 보여줘요.',
    ba: ['SU53 캡처 받아 Basis에 전달', '원인 · 해결 역할 · SoD 영향 한 번에'],
    shots: [['auth-triage', 'skills/auth-triage', '권한 오류 분석 — 판정, 검사 내용, 후보 역할']] },
  { g: 'ops', id: 'symptom', menu: '증상 분석', title: '덤프·오류가 나면 증상만 적어요. 근본 원인을 찾아줘요.',
    desc: '덤프, 이관 이력, where-used를 따라가며 가설을 좁혀요. 스크린샷을 붙여 넣어도 돼요. 시스템은 바꾸지 않아요.',
    ba: ['ST22 → 소스 → 이관 이력 수작업', '증상 입력 → 원인 보고서'],
    shots: [['symptom', 'skills/analyze-symptom', '증상 분석 입력 화면']] },
  { g: 'ops', id: 'monitor', menu: 'MCP 모니터', title: 'AI가 SAP에서 무엇을 했는지 전부 기록으로 남아요.',
    desc: '에이전트가 부른 도구와 입력값, 응답 시간, 실패·거부 건수를 실시간으로 봐요. 감사 대응에도 쓸 수 있어요.',
    ba: ['AI가 뭘 했는지 알 수 없음', '호출 하나하나 투명하게'],
    shots: [['monitor', 'monitor', 'MCP 모니터 — 최근 7일 호출과 실시간 로그']] },

  { g: 'pmo', id: 'dash', menu: '프로젝트 대시보드', title: '여러 프로젝트의 진척과 위험을 한 화면에서 봐요.',
    desc: '진척(실적/계획), 다음 마일스톤, 지연·주의 KPI, WRICEF를 모아요. 프로젝트를 누르면 KPI, WBS, 팀, SAP 실적까지 이어져요.',
    ba: ['매주 담당자에게 취합', '프로젝트 포트폴리오 자동 집계'],
    shots: [['wbs-list', 'wbs', '프로젝트 대시보드 — 전체 프로젝트'], ['wbs-summary', 'wbs/…', '프로젝트 요약 — 주의·위험 KPI'], ['wbs-table', 'wbs/…', 'WBS 표 — 계획 대비 실적 공수']] },
  { g: 'pmo', id: 'weekly', menu: '주간 현황 · 컷오버 준비', title: '주간 보고와 컷오버 계획을 문서로 쓰고 버전으로 남겨요.',
    desc: '워크스트림별 RAG, 이번 주 요약, 컷오버 런북과 Go/No-Go를 한 문서로 관리해요. 바뀐 내용은 대시보드에 반영돼요.',
    ba: ['PPT·엑셀 따로 관리', '문서 하나로 쓰고 대시보드에 반영'],
    shots: [['weekly', 'weekly', '주간 현황 — 워크스트림 RAG'], ['cutover', 'cutover', '컷오버 계획 — 다운타임, Go/No-Go, 런북']] },
  { g: 'pmo', id: 'roles', menu: '권한 매트릭스', title: '역할 × T-code 권한표와 SoD 충돌을 자동으로 정리해요.',
    desc: '업무 역할, 기술 역할, 사용자 배정을 표로 만들고 SoD 규칙으로 점검해요. 고칠 때마다 충돌을 다시 계산해요.',
