const css = `
:root{--bg:#f5f6f8;--card:#fff;--ink:#1c2029;--sub:#5b6474;--line:#e3e6ee;--brand:#0a66c2;--soft:#e6f0fb}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#111317;--card:#171a1f;--ink:#e6e9ee;--sub:#a0a8b6;--line:#2a2f38;--soft:#16273d}}
:root[data-theme="dark"]{--bg:#111317;--card:#171a1f;--ink:#e6e9ee;--sub:#a0a8b6;--line:#2a2f38;--soft:#16273d}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:"Noto Sans KR",system-ui,sans-serif;line-height:1.6;word-break:keep-all}
.wrap{max-width:1180px;margin:0 auto;padding:0 16px}
