.map h4{margin:0 0 8px;font-size:15px}
.map a,.map span{display:block;font-size:13.5px;padding:3px 8px;border-radius:8px;margin:1px -8px;color:var(--sub);text-decoration:none}
.map a{color:var(--ink);font-weight:700}.map a:hover{background:var(--soft)}
.map a::after{content:" ●";color:var(--c);font-size:9px;vertical-align:2px}
.legend{font-size:13px;color:var(--sub);margin-top:8px}
.grp{display:flex;align-items:center;gap:10px;margin:60px 0 16px}
