@media (max-width:960px){.hero,.callout{grid-template-columns:1fr}.map{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:1fr 1fr}.shots.n2,.shots.n3{grid-template-columns:1fr}}
@media (max-width:560px){.map,.steps{grid-template-columns:1fr}.feat{padding:16px}.hero{padding-top:32px}}
`;

const shown = new Set(F.flatMap((f) => f.menu.split(' · ')));
let h = `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>sc4sap 웹 핵심기능</title>
<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700;900&display=swap" rel="stylesheet"><style>${css}</style></head><body><div class="wrap">
<section class="hero"><div><span class="tag">sc4sap 웹 · workspace.sc4sap.dev</span>
<h1>설치 없이<br><em>브라우저 하나로</em><br>SAP 업무를 해요.</h1>
<p class="lead">로그인하고 우리 SAP를 연결하면 끝이에요. 메뉴에서 고르거나 채팅으로 물으면 AI가 시스템을 읽고 문서를 만들어요.</p>
<div class="bl"><b class="k">결론부터</b><ul><li>PMO · 컨설턴트 · 개발자 · SM 운영, <b>역할별 메뉴 30여 개</b>가 한 화면에 있어요.</li><li>결과는 <b>바로 고칠 수 있는 문서</b>로 남고, 옆의 <b>AI 챗</b>으로 다듬어요.</li><li>아래 화면은 모두 <b>실제 웹 화면</b>이에요.</li></ul></div></div>
<div>${frame(['home', '', '홈 — 역할별 시작 메뉴와 최근 작업'], true)}</div></section>
<h2>한눈에 보기</h2><p class="h2s">실제 웹 메뉴 구성이에요. 굵은 항목은 아래에 화면이 있어요.</p>
<div class="map">${GROUPS.map((g) => `<div class="col" style="--c:${g.color}"><h4>${g.icon} ${g.name}</h4>${g.menu.map((m) => { const f = F.find((x) => x.menu.split(' · ').includes(m)); return f ? `<a href="#w-${f.id}">${m}</a>` : `<span>${m}</span>`; }).join('')}</div>`).join('')}</div>
<p class="legend">● 표시 = 아래에서 실제 화면으로 소개하는 기능</p>
<h2>모든 문서 옆에 AI 챗이 있어요</h2><p class="h2s">문서를 열면 오른쪽에 AI 챗이 붙어요. 말로 고치라고 하면 고친 안을 만들어 반영해요.</p>
<div class="callout"><div><b style="font-size:18px">"SoD 위험 설명을 감사인이 읽기 쉽게 다듬어 줘"</b><ul><li>권한 매트릭스, UAT, 주간 보고, 컷오버, Gap, 설정 문서 어디서나 같아요.</li><li>숫자·담당자·결정 같은 사실은 AI가 바꾸지 않아요.</li><li>바꾼 내용은 버전으로 남아 되돌릴 수 있어요.</li></ul></div>
<div>${frame(['roles-cover', 'roles', '권한 매트릭스 문서 + 오른쪽 AI 챗 패널'])}</div></div>`;

for (const g of GROUPS) {
  const fs = F.filter((f) => f.g === g.id);
  if (!fs.length) continue;
  h += `<div class="grp" style="--c:${g.color}"><span>${g.icon}</span><h3>${g.name}</h3></div>`;
  for (const f of fs) {
    h += `<section class="feat" id="w-${f.id}" style="--c:${g.color}"><div class="fh"><span class="fn">${f.menu}</span><span class="mn">메뉴: ${g.name} › ${f.menu}</span></div>
<h3 class="t">${f.title}</h3><p class="d">${f.desc}</p><div class="ba"><span class="b">지금: ${f.ba[0]}</span>→<span class="a">sc4sap: ${f.ba[1]}</span></div>
<div class="shots n${f.shots.length}">${f.shots.map((s) => frame(s)).join('')}</div></section>`;
  }
}

h += `<h2>걱정하실 부분, 먼저 막아뒀어요</h2><p class="h2s">AI가 운영 시스템을 망칠 수 없게 설계했어요.</p><div class="safe">
<div><b>🔒 QA·PRD는 읽기 전용</b>운영 시스템에는 변경이 나가지 않아요.</div>
