.lead{font-size:18px;color:var(--sub);margin:0 0 18px}
.bl{background:var(--card);border:2px solid var(--brand);border-radius:14px;padding:16px 20px}
.bl b.k{color:var(--brand)}.bl ul{margin:6px 0 0;padding-left:20px}
h2{font-size:clamp(22px,3vw,30px);margin:64px 0 6px;font-weight:900}
