.feat h3.t{font-size:clamp(19px,2.4vw,24px);margin:4px 0 6px;line-height:1.35}
.feat p.d{margin:0 0 12px;color:var(--sub)}
.ba{display:inline-flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:14px;margin-bottom:16px}
.ba .b{background:#fdf2e3;color:#92400e;border-radius:8px;padding:3px 10px}
.ba .a{background:#e5f6ef;color:#0f6b4a;border-radius:8px;padding:3px 10px;font-weight:700}
.shots{display:grid;gap:16px}
.shots.n2{grid-template-columns:1fr 1fr}.shots.n3{grid-template-columns:1fr 1fr}
.shots.n3 .fr:first-child{grid-column:1/-1}
.fr{margin:0;border-radius:10px;overflow:hidden;border:1px solid #2a2f38;background:#0f1115;box-shadow:0 12px 30px rgba(10,20,40,.18);min-width:0}
.fr .bar{display:flex;align-items:center;gap:6px;background:#23262d;padding:7px 10px}
.fr .bar i{width:10px;height:10px;border-radius:50%;background:#ff5f57}.fr .bar i:nth-child(2){background:#febc2e}.fr .bar i:nth-child(3){background:#28c840}
