.steps li::before{content:counter(s);position:absolute;left:14px;top:12px;width:26px;height:26px;border-radius:50%;background:var(--brand);color:#fff;font-weight:700;display:grid;place-items:center;font-size:13px}
footer{color:var(--sub);font-size:13.5px;padding:48px 0 60px}
#zoom{position:fixed;inset:0;background:rgba(0,0,0,.85);display:none;align-items:center;justify-content:center;padding:16px;z-index:9;cursor:zoom-out}
#zoom img{max-width:100%;max-height:100%;border-radius:8px}
#zoom.on{display:flex}
@media (max-width:960px){.hero,.callout{grid-template-columns:1fr}.map{grid-template-columns:repeat(2,1fr)}.steps{grid-template-columns:1fr 1fr}.shots.n2,.shots.n3{grid-template-columns:1fr}}
@media (max-width:560px){.map,.steps{grid-template-columns:1fr}.feat{padding:16px}.hero{padding-top:32px}}
`;

